// *** EDIT THIS NODE ***
// CALLBACK_URL examples:
//   Production : https://yourdomain.com/api/webhook/whatsapp-status
//   Local dev  : https://xxxx.ngrok-free.app/api/webhook/whatsapp-status  (use ngrok)
const CALLBACK_URL = "https://finkfold-priyanka-school.vercel.app/api/webhook/whatsapp-status";
// Same secret as node 1
const SECRET = "finkfold_priyanka_2026";

const meta = $input.first().json;
const d = $("2. Build Payload (EDIT ME)").first().json._input;
const msgId = meta?.messages?.[0]?.id || null;
const status = msgId ? "delivered" : "failed";

return [{
  _callbackUrl: CALLBACK_URL,
  _secret: SECRET,
  _body: {
    school_id: d.school_id,
    session_id: d.session_id || null,
    student_id: d.student_id,
    parent_phone: d.parent_phone,
    event_type: d.event_type,
    attendance_date: d.attendance_date,
    template_name: d.event_type === "absent" ? "school_absence_alert_v1" : "school_correction_v1",
    status: status,
    meta_message_id: msgId,
    is_test: false
  }
}];

// *** EDIT THIS NODE ***
// WA_PHONE_NUMBER_ID : Meta Business Manager > WhatsApp Manager > API Setup
// WA_ACCESS_TOKEN    : Meta Business Manager > System Users > Generate Token
const WA_PHONE_NUMBER_ID = "1238881155971579";
const WA_ACCESS_TOKEN    = "EAAVQwyCZCZAL0BSXkBTo8HabR5LHhxZAEG3vhGyGuYIcCpdtQZCSvl5rkoLbmlAFqyZAeaiO9zHA6QaqtAqqMsVNbu8WEGXZBfmsGGwess3UAIklXwCyotZB0K2dL9ZCg0XZBZACw4ZBOyPQOVZBUpSLbWs8cIydXtlW2v6UzjYk63jPv0i8BN7SH8zqdI331k05BQZDZD";

const d = $input.first().json;
const tpl = d.event_type === "absent" ? "school_absence_alert_v1" : "school_correction_v1";

return [{
  _url: `https://graph.facebook.com/v19.0/${WA_PHONE_NUMBER_ID}/messages`,
  _token: WA_ACCESS_TOKEN,
  _input: d,
  _payload: JSON.stringify({
    messaging_product: "whatsapp",
    recipient_type: "individual",
    to: d.parent_phone,
    type: "template",
    template: {
      name: tpl,
      language: { code: "en" },
      components: [{ type: "body", parameters: [
        { type: "text", text: d.parent_name || "Parent" },
        { type: "text", text: d.student_name },
        { type: "text", text: d.class_label },
        { type: "text", text: d.attendance_date }
      ]}]
    }
  })
}];

// *** EDIT THIS NODE ***
// Paste same value as N8N_ATTENDANCE_WEBHOOK_SECRET in your Finkfold .env.local
const EXPECTED_SECRET = "finkfold_priyanka_2026";

const body = $input.first().json;
const headers = body.headers || {};
const incoming = headers["x-finkfold-secret"] || headers["X-Finkfold-Secret"] || "";

if (EXPECTED_SECRET !== "finkfold_priyanka_2026" && incoming !== EXPECTED_SECRET) {
  throw new Error("Unauthorized: invalid x-finkfold-secret");
}
return [body.body || body];
